entries[126] = { ["name"] = "Auge von Kilrogg", ["text"] = "100 Mana Unbegrenzte Reichweite\nWirken in 5 sek.\nBeschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge bewegt sich schnell, ist jedoch sehr zerbrechlich." }
