entries[526] = { ["name"] = "Vergiftung heilen", ["text"] = "7% von Grundmana 40 Meter Reichweite\nSofort\nHeilt 1 Gifteffekt eines Ziels." }
entries[527] = { ["name"] = "Magiebannung", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nBannt auf dem Ziel liegende Magie und entfernt 1 schädlichen Zauber von einem Freund oder 1 nützlichen Zauber von einem Feind." }
entries[528] = { ["name"] = "Krankheit heilen", ["text"] = "12% von Grundmana 40 Meter Reichweite\nSofort\nEntfernt 1 Krankheit von einem befreundeten Ziel." }
entries[529] = { ["name"] = "Blitzschlag", ["text"] = "25 Mana 30 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 28 bis 33 Naturschaden zu." }
entries[530] = { ["name"] = "Bezauberung (Besitz ergreifen)" }
entries[543] = { ["name"] = "Feuerzauberschutz", ["text"] = "85 Mana\nSofort 30 sek. Abklingzeit\nAbsorbiert 165 Feuerschaden. Hält 30 Sek. lang an." }
entries[546] = { ["name"] = "Wasserwandeln", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nReagenzien:\nFischöl\nErmöglicht dem befreundeten Ziel, 10 Min. lang auf Wasser zu wandern. Jeglicher erlittene Schaden hebt den Effekt wieder auf." }
entries[547] = { ["name"] = "Welle der Heilung", ["text"] = "80 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 136 bis 163." }
entries[548] = { ["name"] = "Blitzschlag", ["text"] = "40 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 48 bis 57 Naturschaden zu." }
entries[550] = { ["name"] = "Gift neutralisieren", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nDas Ziel ist 30 Sek. lang gegen Gift immun und wird von allen bereits vorhandenen Giften geheilt." }
entries[552] = { ["name"] = "Krankheit aufheben", ["text"] = "12% von Grundmana 40 Meter Reichweite\nSofort\nVersucht, beim Ziel 1 Krankheitseffekt und 20 Sek. lang alle 5 Sek. 1 weiteren Krankheitseffekt zu heilen." }
entries[553] = { ["name"] = "Wellensturm 2" }
entries[555] = { ["name"] = "Wildgeist", ["text"] = "22 Mana\nWirken in 3 sek." }
entries[556] = { ["name"] = "Astraler Rückruf", ["text"] = "150 ManaWirken in 10 sek. 15 min Abklingzeit\nReißt den Zaubernden durch den wirbelnden Nether zurück nach Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern." }
entries[563] = { ["name"] = "Mondfeuer", ["text"] = "Wirken in 3 sek." }
entries[568] = { ["name"] = "Arkane Wucht" }
entries[578] = { ["name"] = "Schwarzer Wolf", ["text"] = "Wirken in 3 sek.\nBeschwört einen reitbaren schwarzen Wolf oder gibt ihn frei." }
entries[579] = { ["name"] = "Roter Wolf", ["text"] = "Wirken in 3 sek.\nBeschwört einen reitbaren roten Wolf oder gibt ihn frei." }
entries[580] = { ["name"] = "Großer Waldwolf", ["text"] = "Wirken in 3 sek.\nBeschwört einen reitbaren Waldwolf oder gibt ihn frei." }
entries[581] = { ["name"] = "Winterwolf", ["text"] = "Wirken in 3 sek.\nBeschwört einen reitbaren Winterwolf oder gibt ihn frei." }
entries[585] = { ["name"] = "Göttliche Pein", ["text"] = "20 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nZerschmettert einen Feind und fügt ihm 15 bis 20 Heiligschaden zu." }
entries[586] = { ["name"] = "Verblassen", ["text"] = "40 Mana\nSofort 30 sek. Abklingzeit\nLässt den Zaubernden verblassen und entmutigt Feinde 10 Sek. lang, Euch anzugreifen." }
entries[587] = { ["name"] = "Essen herbeizaubern", ["text"] = "60 Mana\nWirken in 3 sek.\nZaubert 20 Muffins herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[588] = { ["name"] = "Inneres Feuer", ["text"] = "30 Mana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 315 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[589] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "25 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang insgesamt 30 Schattenschaden zufügt." }
entries[591] = { ["name"] = "Göttliche Pein", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 2 sek.\nZerschmettert einen Feind und fügt ihm 28 bis 34 Heiligschaden zu." }
entries[592] = { ["name"] = "Machtwort: Schild", ["text"] = "80 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 94 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
entries[594] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "50 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang insgesamt 66 Schattenschaden zufügt." }
entries[596] = { ["name"] = "Gebet der Heilung", ["text"] = "410 Mana\nWirken in 3 sek.\nEin wirkungsvolles Gebet heilt alle Gruppenmitglieder in einem Umkreis von 30 Metern um 312 bis 333." }
entries[597] = { ["name"] = "Essen herbeizaubern", ["text"] = "105 Mana\nWirken in 3 sek.\nZaubert 20 Laibe Brot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[598] = { ["name"] = "Göttliche Pein", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerschmettert einen Feind und fügt ihm 58 bis 67 Heiligschaden zu." }
entries[600] = { ["name"] = "Machtwort: Schild", ["text"] = "130 Mana 40 Meter Reichweite\nSofort 4 sek. Abklingzeit\nNutzt die Seelenkraft des Gruppenmitglieds zum Abschirmen und absorbiert dabei 166 Schaden. Hält 30 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 Sek. lang nicht wieder abgeschirmt werden." }
entries[601] = { ["name"] = "Schwertbeherrschung", ["text"] = "Erhöht Eure Angriffswertung mit Einhandschwertern um 3." }
entries[602] = { ["name"] = "Inneres Feuer", ["text"] = "105 Mana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 720 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[603] = { ["name"] = "Fluch der Verdammnis", ["text"] = "300 Mana 30 Meter Reichweite\nSofort 1 min Abklingzeit\nVerflucht das Ziel mit drohender Verdammnis und fügt nach 1 Min. 3200 Schattenschaden zu. Wenn das Ziel durch diesen Schaden stirbt, besteht die Chance, dass eine Verdammniswache beschworen wird. Kann nicht auf Spieler gewirkt werden." }
entries[604] = { ["name"] = "Magie dämpfen", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 10 und Heilzauber um bis zu 20 verringert werden. Hält 10 Min. lang an." }
entries[605] = { ["name"] = "Gedankenkontrolle", ["text"] = "350 Mana 20 Meter Reichweite\nWirken in 3 sek." }
entries[606] = { ["name"] = "Gedankenverfall", ["text"] = "240 Mana 30 Meter Reichweite\nWirken in 2 sek.\nEntzieht dem Ziel 30 Sek. lang insgesamt 2160 Mana." }
entries[611] = { ["name"] = "Siegel der Aufopferung", ["text"] = "Wirken in 3 sek." }
entries[633] = { ["name"] = "Handauflegung", ["text"] = "40 Meter Reichweite\nSofort 1 Stunde Abklingzeit\nHeilt ein befreundetes Ziel bis zur maximalen Gesundheit des Paladins. Entzieht dem Paladin bei Verwendung sämtliches noch vorhandenes Mana." }
entries[635] = { ["name"] = "Heiliges Licht", ["text"] = "35 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 42 bis 51." }
entries[639] = { ["name"] = "Heiliges Licht", ["text"] = "60 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 81 bis 96." }
entries[642] = { ["name"] = "Gottesschild", ["text"] = "75 Mana\nSofort 5 min Abklingzeit\nSchützt den Paladin 10 Sek. lang vor allen Schäden und Zaubern, erhöht jedoch die Zeit zwischen seinen Angriffen um 100%. Einmal geschützt, kann der Paladin 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden oder Zornige Vergeltung nutzen." }
entries[643] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGibt Gruppenmitgliedern in einem Umkreis von 30 Metern 275 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[647] = { ["name"] = "Heiliges Licht", ["text"] = "110 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 167 bis 196." }
entries[668] = { ["name"] = "Sprache Globalisch" }
entries[669] = { ["name"] = "Sprache Orcisch" }
entries[670] = { ["name"] = "Sprache Taurisch" }
entries[671] = { ["name"] = "Sprache Darnassisch" }
entries[672] = { ["name"] = "Sprache Zwergisch" }
entries[673] = { ["name"] = "Geringe Rüstung", ["text"] = "Sofort\nErhöht die Rüstung 1 Stunde lang um 50. Wächterelixier." }
entries[674] = { ["name"] = "Beidhändigkeit", ["text"] = "Ermöglicht die Verwendung von einhändigen Waffen und Schildhandwaffen in der Schildhand." }
entries[676] = { ["name"] = "Entwaffnen", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber 1 min Abklingzeit\nBenötigt Verteidigungshaltung\nEntwaffnet den Gegner 10 Sek. lang." }
entries[686] = { ["name"] = "Schattenblitz", ["text"] = "25 Mana 30 Meter Reichweite\nWirken in 1.7 sek.\nSendet einen schattigen Blitz zum Gegner, der 13 bis 18 Schattenschaden verursacht." }
entries[687] = { ["name"] = "Dämonenhaut", ["text"] = "20 Mana\nSofort\nSchützt den Zaubernden, indem es 30 Min. lang die Rüstung um 40 erhöht und 3 Gesundheit alle 5 Sek. wiederherstellt." }
entries[688] = { ["name"] = "Wichtel beschwören", ["text"] = "64% von Grundmana\nWirken in 10 sek.\nBeschwört einen Wichtel, der unter dem Befehl des Hexenmeisters steht." }
entries[689] = { ["name"] = "Blutsauger", ["text"] = "55 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 10 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[691] = { ["name"] = "Teufelsjäger beschwören", ["text"] = "80% von Grundmana\nWirken in 10 sek.\nReagenzien:\nSeelensplitter\nBeschwört einen Teufelsjäger, der unter dem Befehl des Hexenmeisters steht." }
entries[693] = { ["name"] = "Seelenstein herstellen", ["text"] = "68% von Grundmana\nWirken in 3 sek.\nReagenzien:\nSeelensplitter\nLässt einen schwachen Seelenstein entstehen. Der Seelenstein kann zum Speichern der Seele eines Ziels benutzt werden. Wenn das Ziel stirbt, während seine Seele gespeichert ist, kann es mit 400 Gesundheit und 700 Mana wiederbelebt werden.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[694] = { ["name"] = "Spöttischer Schlag", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 2 min Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nEin spottender Angriff, der 22 Schaden und ein mittleres Maß an Bedrohung verursacht. Zwingt das Ziel 6 Sek. lang dazu, Angriffe auf Euch zu fokussieren." }
entries[695] = { ["name"] = "Schattenblitz", ["text"] = "40 Mana 30 Meter Reichweite\nWirken in 2.2 sek.\nSendet einen schattigen Blitz zum Gegner, der 26 bis 32 Schattenschaden verursacht." }
entries[696] = { ["name"] = "Dämonenhaut", ["text"] = "48 Mana\nSofort\nSchützt den Zaubernden, indem es 30 Min. lang die Rüstung um 120 erhöht und alle 5 Sek. 5 Gesundheit wiederherstellt." }
entries[697] = { ["name"] = "Leerwandler beschwören", ["text"] = "80% von Grundmana\nWirken in 10 sek.\nReagenzien:\nSeelensplitter\nBeschwört einen Leerwandler, der unter dem Befehl des Hexenmeisters steht." }
entries[698] = { ["name"] = "Ritual der Beschwörung", ["text"] = "300 Mana 30 Meter Reichweite\nWirken in 5 sek.\nReagenzien:\nSeelensplitter\nBeginnt ein Ritual, das das anvisierte Gruppenmitglied beschwört. Um das Ritual zu vervollständigen, werden der Zaubernde und zwei zusätzliche Gruppenmitglieder benötigt. Um teilzunehmen, müssen sich alle Spieler außerhalb eines Kampfes befinden, auf das Portal rechtsklicken und dürfen sich nicht bewegen, bis das Ritual abgeschlossen ist." }
entries[699] = { ["name"] = "Blutsauger", ["text"] = "85 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 17 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[700] = { ["name"] = "Schlaf", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 1.5 sek." }
entries[701] = { ["name"] = "Feuerblitz", ["text"] = "10 Mana 30 Meter Reichweite\nWirken in 3 sek.\nÜberzieht ein Ziel mit 19 Feuerschaden." }
entries[702] = { ["name"] = "Fluch der Schwäche", ["text"] = "20 Mana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 21 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[703] = { ["name"] = "Erdrosseln", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nErdrosselt den Feind und verursacht 18 Sek. lang insgesamt 144 Schaden, erhöht durch Eure Angriffskraft. Muss verstohlen und hinter dem Ziel sein. Gewährt 1 Combopunkt." }
entries[704] = { ["name"] = "Fluch der Tollkühnheit", ["text"] = "35 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Tollkühnheit, wodurch sich die Nahkampfangriffskraft 2 Min. lang um 20 erhöht, jedoch die Rüstung um 140 verringert. Mit einem Fluch belegte Feinde fliehen nicht und ignorieren Furcht- und Entsetzenseffekte. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[705] = { ["name"] = "Schattenblitz", ["text"] = "70 Mana 30 Meter Reichweite\nWirken in 2.8 sek.\nSendet einen schattigen Blitz zum Gegner, der 52 bis 61 Schattenschaden verursacht." }
entries[706] = { ["name"] = "Dämonenrüstung", ["text"] = "110 Mana\nSofort\nSchützt den Zaubernden und erhöht die Rüstung um 210, den Schattenwiderstand um 3 und stellt alle 5 Sek. 7 Gesundheit wieder her. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 Min. an." }
entries[707] = { ["name"] = "Feuerbrand", ["text"] = "45 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Feind und fügt 24 Feuerschaden sowie 15 Sek. lang insgesamt 40 zusätzlichen Feuerschaden zu." }
entries[709] = { ["name"] = "Blutsauger", ["text"] = "135 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nÜberträgt alle 1 Sek. 29 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an." }
entries[710] = { ["name"] = "Verbannen", ["text"] = "100 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerbannt das feindliche Ziel und verhindert damit jegliche Aktion, macht es aber bis zu 20 Sek. lang unverwundbar. Es kann immer nur jeweils ein Ziel verbannt werden. Funktioniert nur bei Dämonen und Elementaren." }
entries[712] = { ["name"] = "Sukkubus beschwören", ["text"] = "80% von Grundmana\nWirken in 10 sek.\nReagenzien:\nSeelensplitter\nBeschwört einen Sukkubus, der unter dem Befehl des Hexenmeisters steht." }
entries[713] = { ["name"] = "Inkubus beschwören", ["text"] = "80% von Grundmana\nWirken in 10 sek.\nReagenzien:\nSeelensplitter\nBeschwört einen Inkubus, der unter dem Befehl des Hexenmeisters steht." }
entries[720] = { ["name"] = "Umschlingen" }
entries[724] = { ["name"] = "Brunnen des Lichts", ["text"] = "225 Mana 40 Meter Reichweite\nWirken in 1.5 sek. 6 min Abklingzeit\nErschafft einen heiligen Brunnen des Lichts. Mitglieder Eurer Gruppe oder Schlachtgruppe können den Brunnen des Lichts anklicken, um im Verlauf von 6 Sek. insgesamt 801 Gesundheit wiederherzustellen. Jeglicher erlittene Schaden bricht den Effekt ab. Der Brunnen des Lichts bleibt 3 Min. lang bestehen oder bis alle 5 Aufladungen verbraucht sind." }
entries[731] = { ["name"] = "Umschlingen" }
entries[740] = { ["name"] = "Gelassenheit", ["text"] = "525 ManaKanalisiert (Wirken in 8 sek.) 10 min Abklingzeit\nHeilt bei allen in der Nähe befindlichen Gruppenmitgliedern 8 Sek. lang alle 2 Sek. 365 Gesundheit. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
entries[742] = { ["name"] = "Pulverisieren", ["text"] = "10 min Abklingzeit\n(Procchance: 35%)" }
entries[744] = { ["name"] = "Gift", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 30 Sek. lang alle 3 Sek. Naturschaden zu." }
entries[745] = { ["name"] = "Gespinst", ["text"] = "30 Meter Reichweite\nSofort\nZaubert ein Netz über einen Feind und macht ihn so 5 Sek. lang bewegungsunfähig." }
entries[746] = { ["name"] = "Erste Hilfe", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nHeilt 6 Sek. lang insgesamt 66 Schaden." }
entries[747] = { ["name"] = "Abbilder beschwören" }
entries[750] = { ["name"] = "Plattenpanzer" }
entries[755] = { ["name"] = "Lebenslinie", ["text"] = "11 Gesundheit und 5 pro Sek. 20 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nGibt dem Begleiter des Zaubernden 10 Sek. lang in jeder Sekunde 12 Gesundheit, solange der Zaubernde seine Kräfte kanalisiert." }
entries[758] = { ["name"] = "Feuerstein passiv", ["text"] = "Verzaubert die Waffenhandwaffe mit Feuer und gewährt jedem Angriff die Chance, 25 bis 35 zusätzlichen Feuerschaden zuzufügen." }
entries[759] = { ["name"] = "Manaachat herbeizaubern", ["text"] = "530 Mana\nWirken in 3 sek.\nZaubert einen Manaachat herbei, der zum sofortigen Wiederherstellen von 390 bis 410 Mana verwendet werden kann.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[768] = { ["name"] = "Katzengestalt", ["text"] = "35% von Grundmana\nSofort\nGestaltwandlung in Katzengestalt, erhöht Nahkampfangriffskraft um 40 plus Beweglichkeit. Beschützt den Zaubernden auch vor Verwandlungseffekten und erlaubt den Einsatz von verschiedenen Katzenfähigkeiten.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von verwandlungs- und bewegungseinschränkenden Effekten." }
entries[769] = { ["name"] = "Prankenhieb", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt 3 in der Nähe befindliche Feinde und verursacht 21 Schaden, erhöht durch Angriffskraft." }
entries[770] = { ["name"] = "Feenfeuer", ["text"] = "55 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 Sek. lang um 175. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[772] = { ["name"] = "Verwunden", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Verteidigungshaltung\nVerwundet das Ziel, lässt es 9 Sek. lang bluten und fügt damit 15 Schaden plus [0.00743 * 3 * ((Haupthandwaffen-Max-Grundschaden + Haupthandwaffen-Min-Grundschaden) / 2 + Angriffskraft / 14 * Haupthandwaffen-Max-Grundgeschwindigkeit)] zusätzlichen Schaden (basierend auf Waffenschaden) zu." }
entries[774] = { ["name"] = "Verjüngung", ["text"] = "25 Mana 40 Meter Reichweite\nSofort\nHeilt beim Ziel 12 Sek. lang insgesamt 32 Schaden." }
entries[778] = { ["name"] = "Feenfeuer", ["text"] = "75 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 40 Sek. lang um 285. Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[779] = { ["name"] = "Prankenhieb", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt 3 in der Nähe befindliche Feinde und verursacht 10 Schaden, erhöht durch Angriffskraft." }
entries[780] = { ["name"] = "Prankenhieb", ["text"] = "20 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nSchlägt 3 in der Nähe befindliche Feinde und verursacht 14 Schaden, erhöht durch Angriffskraft." }
entries[781] = { ["name"] = "Rückzug", ["text"] = "50 Mana Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVersucht, sich vom Ziel zurückzuziehen und verringert dadurch die Bedrohung. Charakter verlässt Kampfmodus." }
entries[782] = { ["name"] = "Dornen", ["text"] = "60 Mana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, 6 Naturschaden zufügen. Hält 10 Min. lang an." }
entries[783] = { ["name"] = "Reisegestalt", ["text"] = "13% von Grundmana\nSofort\nVerwandelt Euch in eine Reisegestalt und erhöht dadurch Euer Bewegungstempo um 40%. Beschützt den Zaubernden auch vor Verwandlungseffekten. Kann nur draußen verwendet werden.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von verwandlungs- und bewegungseinschränkenden Effekten." }
entries[785] = { ["name"] = "Wahre Erfüllung", ["text"] = "260 Mana" }
entries[799] = { ["name"] = "Zwillingsteleport" }
entries[800] = { ["name"] = "Zwillingsteleport", ["text"] = "Sofort" }
entries[802] = { ["name"] = "Käfer mutieren" }
entries[804] = { ["name"] = "Käfer explodieren lassen" }
entries[806] = { ["name"] = "Inbrunst", ["text"] = "Sofort\nErhöht Stärke um 14 und fügt Euch 1 Min. lang alle 15 Sek. 15 Schaden zu." }
entries[812] = { ["name"] = "Regelmäßiger Manabrand", ["text"] = "Unbegrenzte Reichweite\nSofort\nWirkt in regelmäßigen Abständen Manabrand." }
entries[813] = { ["name"] = "Sprache Thalassisch" }
entries[815] = { ["name"] = "Sprache Dämonisch" }
entries[818] = { ["name"] = "Einfaches Lagerfeuer", ["text"] = "Wirken in 10 sek. 5 min Abklingzeit\nTools: Feuerstein und Zunder\nReagenzien:\nEinfaches Holz\nBaut ein Lagerfeuer, das die Willenskraft von jedem in der Nähe um 4 erhöht und das Kochen ermöglicht." }
entries[822] = { ["name"] = "Magiewiderstand", ["text"] = "Alle Widerstände um 5 erhöht." }
entries[823] = { ["name"] = "Naturwiderstand" }
entries[824] = { ["name"] = "Pferdreiten" }
entries[825] = { ["name"] = "Wolfreiten" }
entries[826] = { ["name"] = "Widderreiten" }
entries[827] = { ["name"] = "Nachtmahrreiten", ["text"] = "Erhöht das Reittempo um 0." }
entries[828] = { ["name"] = "Tigerreiten" }
entries[829] = { ["name"] = "Dickschädel", ["text"] = "Sofort" }
entries[830] = { ["name"] = "Furchtlos", ["text"] = "Sofort" }
entries[833] = { ["name"] = "Grüntee", ["text"] = "Sofort\nHeilt sofort 30 Schaden. Stellt im Verlauf von 10 Sek. insgesamt 60 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[834] = { ["name"] = "Geringe Rüstung", ["text"] = "Sofort\nErhöht die Rüstung 1 Stunde lang um 100. Wächterelixier." }
entries[835] = { ["name"] = "Gezeitenglücksbringer", ["text"] = "30 Meter Reichweite\nSofort" }
entries[836] = { ["name"] = "LOGINEFFEKT" }
entries[837] = { ["name"] = "Frostblitz", ["text"] = "50 Mana 30 Meter Reichweite\nWirken in 2.2 sek.\nSchleudert einen Frostblitz auf den Feind, der 54 bis 61 Frostschaden verursacht und 6 Sek. lang das Bewegungstempo um 40% reduziert." }
entries[845] = { ["name"] = "Spalten", ["text"] = "20 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin weitreichender Angriff, der dem Ziel und seinem nächsten Verbündeten Euren Waffenschaden sowie 5 zusätzlichen Schaden zufügt." }
entries[851] = { ["name"] = "Verwandlung: Schaf", ["text"] = "200 Mana 20 Meter Reichweite\nSofort\nVerwandelt den Feind bis zu 10 Sek. lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt." }
entries[853] = { ["name"] = "Hammer der Gerechtigkeit", ["text"] = "30 Mana 10 Meter Reichweite\nSofort 1 min Abklingzeit\nBetäubt das Ziel 3 Sek. lang." }
entries[857] = { ["name"] = "Khadgars Öffnung", ["text"] = "220 Mana 5 Meter Reichweite\nWirken in 10 sek.\nReagenzien:\nWinziger Eisenschlüssel\nSchließt auf magische Weise Schatztruhen und andere verschlossene Gegenstände auf." }
entries[865] = { ["name"] = "Frostnova", ["text"] = "85 Mana\nSofort 25 sek. Abklingzeit\nFügt in der Nähe des Zaubernden befindlichen Feinden 35 bis 40 Frostschaden zu und friert sie bis zu 8 Sek. lang ein. Erlittener Schaden kann den Effekt unterbrechen." }
entries[871] = { ["name"] = "Schildwall", ["text"] = "Sofort 30 min Abklingzeit\nBenötigt Verteidigungshaltung\nVerringert den durch Nahkampfangriffe, Distanzangriffe und Zauber erlittenen Schaden 10 Sek. lang um 75%." }
entries[879] = { ["name"] = "Exorzismus", ["text"] = "70 Mana 30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nVerursacht 90 bis 102 Heiligschaden an einem untoten oder dämonischen Ziel." }
entries[883] = { ["name"] = "Tier rufen", ["text"] = "Sofort\nBeschwört Euer Tier zu Euch." }
entries[886] = { ["name"] = "Unsichtbarkeit", ["text"] = "Wirken in 3 sek.\nLehrt 'Unsichtbarkeit'." }
entries[897] = { ["name"] = "Wütenden Programmierer beschwören" }
entries[898] = { ["name"] = "Inbrunst-Trank herstellen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFaustgroße Spinndrüse\nErstellt einen Trank der Inbrunst." }
entries[905] = { ["name"] = "Blitzschlagschild", ["text"] = "100 Mana\nSofort\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 51 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[913] = { ["name"] = "Welle der Heilung", ["text"] = "155 Mana 40 Meter Reichweite\nWirken in 3 sek.\nHeilt ein befreundetes Ziel um 279 bis 328." }
entries[915] = { ["name"] = "Blitzschlag", ["text"] = "70 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 88 bis 100 Naturschaden zu." }
entries[921] = { ["name"] = "Taschendiebstahl", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nEinen Taschendiebstahl am Ziel begehen." }
entries[930] = { ["name"] = "Kettenblitzschlag", ["text"] = "345 Mana 30 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nSchleudert einen Blitzschlag auf den Feind, der 288 bis 323 Naturschaden verursacht und zu in der Nähe befindlichen Feinden weiterspringt. Jeder Sprung verringert den Schaden um 30%. Wirkt auf insgesamt 3 Ziele." }
entries[932] = { ["name"] = "Geist auffüllen II", ["text"] = "30 Meter ReichweiteWirken in 3 sek. 6 min Abklingzeit\nStellt Mana des Ziels wieder her." }
entries[939] = { ["name"] = "Welle der Heilung", ["text"] = "200 Mana 40 Meter Reichweite\nWirken in 3 sek.\nHeilt ein befreundetes Ziel um 389 bis 454." }
entries[943] = { ["name"] = "Blitzschlag", ["text"] = "95 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz auf das Ziel und fügt ihm 131 bis 149 Naturschaden zu." }
entries[945] = { ["name"] = "Blitzschlagschild", ["text"] = "150 Mana\nSofort\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 80 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[959] = { ["name"] = "Welle der Heilung", ["text"] = "265 Mana 40 Meter Reichweite\nWirken in 3 sek.\nHeilt ein befreundetes Ziel um 552 bis 639." }
entries[970] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang insgesamt 132 Schattenschaden zufügt." }
entries[974] = { ["name"] = "Erdschild", ["text"] = "300 Mana 40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der eine Chance von 30% gewährt, Zauberunterbrechungen durch Schaden zu vermeiden. Angriffe heilen das geschützte Ziel um 150, dieser Effekt tritt aber nur einmal alle paar Sekunden auf. 6 Aufladungen. Hält 10 Min. lang an. Dieser Schild kann immer nur auf einem Ziel gleichzeitig aktiv sein, und auf jedem Ziel kann nur ein Elementarschild aktiv sein.\n(3.5s Abklingzeit)" }
entries[976] = { ["name"] = "Schattenschutz", ["text"] = "250 Mana 30 Meter Reichweite\nSofort\nErhöht 10 Min. lang die Widerstandskraft des Ziels gegen alle Schattenzauber um 30." }
entries[980] = { ["name"] = "Fluch der Pein", ["text"] = "25 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 84 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[982] = { ["name"] = "Tier wiederbeleben", ["text"] = "80% von Grundmana\nWirken in 10 sek.\nBringt Euer totes Tier mit 15% seiner Grundgesundheit wieder ins Leben zurück." }
entries[984] = { ["name"] = "Göttliche Pein", ["text"] = "95 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerschmettert einen Feind und fügt ihm 97 bis 112 Heiligschaden zu." }
entries[988] = { ["name"] = "Magiebannung", ["text"] = "14% von Grundmana 30 Meter Reichweite\nSofort\nBannt auf dem Ziel liegende Magie und entfernt 2 schädliche Zauber von einem Freund oder 2 nützliche Zauber von einem Feind." }
entries[990] = { ["name"] = "Essen herbeizaubern", ["text"] = "180 Mana\nWirken in 3 sek.\nZaubert 20 Laibe Roggenbrot herbei und versorgt den Magier sowie seine Verbündeten mit etwas Essbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt." }
entries[992] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "155 Mana 30 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das 18 Sek. lang insgesamt 234 Schattenschaden zufügt." }
entries[996] = { ["name"] = "Gebet der Heilung", ["text"] = "560 Mana\nWirken in 3 sek.\nEin wirkungsvolles Gebet heilt alle Gruppenmitglieder in einem Umkreis von 30 Metern um 458 bis 487." }
entries[1002] = { ["name"] = "Augen des Wildtiers", ["text"] = "20 Mana Unbegrenzte Reichweite\nWirken in 2 sek.\nLässt Euch die direkte Kontrolle über Euer Tier übernehmen und 1 Min. lang durch seine Augen sehen." }
entries[1004] = { ["name"] = "Göttliche Pein", ["text"] = "140 Mana 30 Meter Reichweite\nWirken in 2.5 sek.\nZerschmettert einen Feind und fügt ihm 158 bis 178 Heiligschaden zu." }
entries[1006] = { ["name"] = "Inneres Feuer", ["text"] = "165 Mana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 945 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 10 Min. lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[1008] = { ["name"] = "Magie verstärken", ["text"] = "150 Mana 30 Meter Reichweite\nSofort\nVerstärkt gegen das anvisierte Gruppenmitglied gerichtete Magie, wobei der von Zaubern zugefügte Schaden um bis zu 15 und Heilzauber um bis zu 30 erhöht werden. Hält 10 Min. lang an." }
entries[1010] = { ["name"] = "Fluch der Torheit", ["text"] = "110 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Torheit, verringert Intelligenz und Willenskraft alle 3 Sek. um 6, bis beides um insgesamt 90 verringert worden ist. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1014] = { ["name"] = "Fluch der Pein", ["text"] = "50 Mana 30 Meter Reichweite\nSofort\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 180 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1020] = { ["name"] = "Gottesschild", ["text"] = "110 Mana\nSofort 5 min Abklingzeit\nSchützt den Paladin 12 Sek. lang vor allen Schäden und Zaubern, erhöht jedoch die Zeit zwischen seinen Angriffen um 100%. Einmal geschützt, kann der Paladin 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden oder Zornige Vergeltung nutzen." }
entries[1022] = { ["name"] = "Segen des Schutzes", ["text"] = "25 Mana 30 Meter Reichweite\nSofort 5 min Abklingzeit\nEin anvisiertes Gruppenmitglied ist 6 Sek. lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein. Einmal geschützt, kann das Ziel 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden." }
entries[1026] = { ["name"] = "Heiliges Licht", ["text"] = "190 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 322 bis 368." }
entries[1032] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nGibt Gruppenmitgliedern in einem Umkreis von 30 Metern 505 zusätzliche Rüstung. Spieler können pro Paladin immer nur jeweils eine Aura besitzen." }
entries[1038] = { ["name"] = "Segen der Rettung", ["text"] = "6% von Grundmana 30 Meter Reichweite\nSofort\nBelegt ein Gruppenmitglied mit einem Segen und verringert dabei jegliche erzeugte Bedrohung 10 Min. lang um 30%. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[1042] = { ["name"] = "Heiliges Licht", ["text"] = "275 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 506 bis 569." }
entries[1044] = { ["name"] = "Segen der Freiheit", ["text"] = "8% von Grundmana 30 Meter Reichweite\nSofort 25 sek. Abklingzeit\nBelegt ein befreundetes Ziel mit einem Segen und befreit es 10 Sek. lang von allen bewegungseinschränkenden Effekten. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein." }
entries[1050] = { ["name"] = "Opferung", ["text"] = "Wirken in 1 sek." }
entries[1058] = { ["name"] = "Verjüngung", ["text"] = "40 Mana 40 Meter Reichweite\nSofort\nHeilt beim Ziel 12 Sek. lang insgesamt 56 Schaden." }
entries[1062] = { ["name"] = "Wucherwurzeln", ["text"] = "65 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nLässt das Ziel an Ort und Stelle festwurzeln und verursacht 15 Sek. lang insgesamt 50 Naturschaden. Erlittener Schaden kann den Effekt unterbrechen. Kann nur draußen verwendet werden." }
entries[1064] = { ["name"] = "Kettenheilung", ["text"] = "260 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das befreundete Ziel um 332 bis 381 und springt dann weiter, um weitere in der Nähe befindliche Ziele zu heilen. Wenn es auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. Nach jedem Sprung verringert sich die Heilwirkung um 50%. Heilt 3 Ziele insgesamt." }
entries[1066] = { ["name"] = "Wassergestalt", ["text"] = "13% von Grundmana\nSofort\nGestaltwandlung in eine Wassergestalt. Das Schwimmtempo wird um 50% erhöht und der Druide kann unter Wasser atmen. Beschützt den Zaubernden auch vor Verwandlungseffekten.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von verwandlungs- und bewegungseinschränkenden Effekten." }
entries[1075] = { ["name"] = "Dornen", ["text"] = "105 Mana 30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, 9 Naturschaden zufügen. Hält 10 Min. lang an." }
entries[1079] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: 12 Sek. lang 42 Schaden.\n2 Punkte: 12 Sek. lang 66 Schaden.\n3 Punkte: 12 Sek. lang 90 Schaden.\n4 Punkte: 12 Sek. lang 114 Schaden.\n5 Punkte: 12 Sek. lang 138 Schaden." }
entries[1082] = { ["name"] = "Klaue", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nDen Feind mit Klauen beharken und ihm so zusätzlich 27 Schaden zufügen. Gewährt 1 Combopunkt." }
entries[1086] = { ["name"] = "Dämonenrüstung", ["text"] = "208 Mana\nSofort\nSchützt den Zaubernden und erhöht die Rüstung um 300, den Schattenwiderstand um 6 und stellt alle 5 Sek. 9 Gesundheit wieder her. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 Min. an." }
entries[1088] = { ["name"] = "Schattenblitz", ["text"] = "110 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSendet einen schattigen Blitz zum Gegner, der 92 bis 104 Schattenschaden verursacht." }
entries[1090] = { ["name"] = "Schlaf", ["text"] = "90 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nVersetzt das feindliche Ziel bis zu 30 Sek. lang in Schlaf. Jeglicher zugefügte Schaden wird das Ziel wieder aufwecken. Es kann immer nur jeweils ein Ziel schlafen." }
entries[1094] = { ["name"] = "Feuerbrand", ["text"] = "90 Mana 30 Meter Reichweite\nWirken in 2 sek.\nVerbrennt den Feind und fügt 53 Feuerschaden sowie 15 Sek. lang insgesamt 90 zusätzlichen Feuerschaden zu." }
entries[1098] = { ["name"] = "Dämon unterwerfen", ["text"] = "300 Mana 30 Meter Reichweite\nWirken in 3 sek.\nReagenzien:\nSeelensplitter" }
entries[1106] = { ["name"] = "Schattenblitz", ["text"] = "160 Mana 30 Meter Reichweite\nWirken in 3 sek.\nSendet einen schattigen Blitz zum Gegner, der 150 bis 170 Schattenschaden verursacht." }
entries[1108] = { ["name"] = "Fluch der Schwäche", ["text"] = "35 Mana 30 Meter Reichweite\nSofort\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 41 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[1120] = { ["name"] = "Seelendieb", ["text"] = "55 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nEntzieht dem Ziel die Seele und verursacht 15 Sek. lang insgesamt 55 Schattenschaden. Wenn das Ziel beim Entziehen der Seele stirbt und Erfahrung oder Ehrenpunkte abgibt, erhält der Zaubernde einen Seelensplitter. Seelensplitter werden für andere Zauber benötigt." }
entries[1121] = { ["name"] = "Umschlingen" }
entries[1122] = { ["name"] = "Inferno", ["text"] = "80% von Grundmana 30 Meter Reichweite\nWirken in 2 sek. 1 Stunde Abklingzeit\nReagenzien:\nHöllenstein\nBeschwört einen Meteor aus dem Wirbelnden Nether, der 200 Feuerschaden verursacht und alle gegnerischen Ziele im Gebiet 2 Sek. lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 5 Min. lang unter dem Befehl des Zaubernden steht. Sobald die Kontrolle verloren ist, muss die Höllenbestie unterworfen werden, um sie unter Kontrolle zu halten. Kann nur draußen verwendet werden." }
entries[1126] = { ["name"] = "Mal der Wildnis", ["text"] = "20 Mana 30 Meter Reichweite\nSofort\nErhöht 30 Min. lang die Rüstung des befreundeten Ziels um 25." }
entries[1127] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 27 Sek. insgesamt 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1129] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. insgesamt 1392 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1130] = { ["name"] = "Mal des Jägers", ["text"] = "15 Mana 100 Meter Reichweite\nSofort\nLegt das Mal des Jägers auf das Ziel und erhöht dabei die Distanzangriffskraft aller Angreifer gegen dieses Ziel um 20 sowie jedesmal, wenn es durch einen Distanzangriff getroffen wird, um zusätzliche 2 bis zu einem Höchstbetrag von 80. Zusätzlich ist mit dieser Fähigkeit das Ziel immer sichtbar, auch wenn es in den Verstohlenheitsmodus geht oder unsichtbar wird. Das Ziel wird außerdem auf der Minikarte angezeigt. Hält 2 Min. lang an." }
entries[1131] = { ["name"] = "Essen", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. insgesamt 2148 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1132] = { ["name"] = "Kritischer Treffer" }
entries[1133] = { ["name"] = "Trinken", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 27 Sek. insgesamt 1345 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[1135] = { ["name"] = "Trinken", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. insgesamt 1992 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[1137] = { ["name"] = "Trinken", ["text"] = "Sofort 1 min Abklingzeit\nStellt im Verlauf von 30 Sek. insgesamt 2934 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[1138] = { ["name"] = "Kristallschutz", ["text"] = "30 Meter Reichweite\nSofort\nVerstärkt Frost- und Schattenwiderstand 1 Min. lang um 10." }
entries[1139] = { ["name"] = "Kaltauge", ["text"] = "30 Meter Reichweite\nSofort\nErhöht 15 Sek. lang die Zeit zwischen Angriffen des Ziels um 5%." }
entries[1152] = { ["name"] = "Läutern", ["text"] = "6% von Grundmana 40 Meter Reichweite\nSofort\nLäutert ein befreundetes Ziel und hebt dabei 1 Krankheitseffekt und 1 Gifteffekt auf." }
entries[1159] = { ["name"] = "Erste Hilfe", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nHeilt 6 Sek. lang insgesamt 114 Schaden." }
entries[1160] = { ["name"] = "Demoralisierender Ruf", ["text"] = "10 Wut\nSpontanzauber\nVerringert 30 Sek. lang die Nahkampfangriffskraft von Feinden innerhalb eines Radius von 10 Metern um 45." }
entries[1161] = { ["name"] = "Herausforderungsruf", ["text"] = "5 WutSpontanzauber 10 min Abklingzeit\nZwingt alle Feinde in einem Umkreis von 10 Metern, 6 Sek. lang ihre Angriffe auf Euch zu konzentrieren." }
entries[1178] = { ["name"] = "Bärengestalt (passiv)", ["text"] = "Benötigt Bärengestalt" }
entries[1180] = { ["name"] = "Dolche" }
entries[1206] = { ["name"] = "REUSE" }
entries[1234] = { ["name"] = "Tony's God Mode", ["text"] = "Unbegrenzte Reichweite\nSofort 0.5 sek. Abklingzeit\nTödlicher Schaden wird absorbiert.\nHeilt alle 5 Sek. 100% Gesundheit." }
entries[1243] = { ["name"] = "Machtwort: Seelenstärke", ["text"] = "20 Mana 30 Meter Reichweite\nSofort\nMacht erfüllt das Ziel und erhöht 30 Min. lang seine Ausdauer um 3." }
entries[1244] = { ["name"] = "Machtwort: Seelenstärke", ["text"] = "70 Mana 30 Meter Reichweite\nSofort\nMacht erfüllt das Ziel und erhöht 30 Min. lang seine Ausdauer um 8." }
