entries[1680] = { ["name"] = "Wirbelwind", ["text"] = "25 Wut\nSpontanzauber 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Berserkerhaltung\nIn einem stählernen Wirbel greift Ihr bis zu 4 Feinde in einem Umkreis von 8 Metern an und verursacht Waffenschaden beider Nahkampfwaffen bei jedem Feind." }
entries[1706] = { ["name"] = "Levitieren", ["text"] = "100 Mana\nSofort\nReagenzien:\nLeichte Feder\nErmöglicht dem Zaubernden zu levitieren und damit wenige Schritte über dem Boden zu fliegen. Beim Levitieren fallt Ihr mit reduziertem Tempo und könnt wasserähnliche Oberflächen überwinden. Jeglicher erlittene Schaden hebt den Effekt wieder auf. Hält 2 Min. lang an." }
