entries[1714] = { ["name"] = "Fluch der Sprachen", ["text"] = "80 Mana 30 Meter Reichweite\nSofort\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 50%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 Sek. lang an." }
entries[1715] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung, Berserkerhaltung\nVerstümmelt den Feind, wobei 5 Schaden verursacht werden und das Bewegungstempo des Feindes 15 Sek. lang um 40% verlangsamt wird." }
entries[1719] = { ["name"] = "Tollkühnheit", ["text"] = "Sofort 30 min Abklingzeit\nBenötigt Berserkerhaltung\nDer Krieger verursacht für die nächsten 15 Sek. mit den meisten Angriffen kritischen Schaden und ist gegen Furchteffekte immun. Jeglicher erlittene Schaden wird allerdings um 20% erhöht." }
entries[1725] = { ["name"] = "Ablenken", ["text"] = "30 Energie 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBewirkt eine Ablenkung, die die Aufmerksamkeit aller in der Nähe befindlichen Monster 10 Sek. lang auf sich zieht. Lässt Verstohlenheit weiterbestehen." }
entries[1735] = { ["name"] = "Demoralisierendes Gebrüll", ["text"] = "10 Wut\nSpontanzauber\nBenötigt Bärengestalt, Terrorbärengestalt\nDer Druide brüllt und verringert damit die Nahkampfangriffskraft von in der Nähe befindlichen Feinden um 60. Hält 30 Sek. lang an." }
