entries[1943] = { ["name"] = "Blutung", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden im Lauf der Zeit verursacht, erhöht durch Angriffskraft. Hält pro Combopunkt länger an:\n1 Punkt: 40 Schaden über 8 Sekunden.\n2 Punkte: 60 Schaden über 10 Sekunden.\n3 Punkte: 84 Schaden über 12 Sekunden.\n4 Punkte: 112 Schaden über 14 Sekunden.\n5 Punkte: 144 Schaden über 16 Sekunden" }
entries[1949] = { ["name"] = "Höllenfeuer", ["text"] = "645 Mana\nKanalisiert (Wirken in 15 sek.)\nEntzündet den Bereich um den Zaubernden herum, fügt ihm selbst alle 1 Sek. 87 Feuerschaden zu sowie im gleichen Rythmus allen in der Nähe befindlichen Feinden 87 Feuerschaden. Hält 15 Sek. lang an." }
entries[1950] = { ["name"] = "Großer Schattenwichtel" }
entries[1953] = { ["name"] = "Blinzeln", ["text"] = "21% von Grundmana\nSofort 15 sek. Abklingzeit\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungen und Banden." }
entries[1966] = { ["name"] = "Finte", ["text"] = "20 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nEin Täuschungsmanöver wird durchgeführt, das zwar keinen Schaden verursacht, aber Eure Bedrohung um ein kleines Maß verringert und die Wahrscheinlichkeit senkt, dass der Feind Euch angreift." }
entries[1978] = { ["name"] = "Schlangenbiss", ["text"] = "15 Mana 35 Meter Reichweite\nBenötigt Distanzwaffe\nBeißt das Ziel und verursacht 15 Sek. lang (Fernkampfangriffskraft * 0.1 + 4 * 5) Naturschaden. Es kann immer nur ein Biss oder Stich pro Jäger auf einem einzelnen Ziel aktiv sein." }
