entries[2008] = { ["name"] = "Geist der Ahnen", ["text"] = "72% von Grundmana 30 Meter Reichweite\nWirken in 10 sek.\nLässt den Geist in den Körper zurückkehren und bringt ein totes Ziel mit 65 Gesundheit und 120 Mana wieder ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
