entries[2048] = { ["name"] = "Schlachtruf", ["text"] = "10 Wut\nSpontanzauber\nDer Krieger lässt einen wilden Schlachtruf ertönen, der bei allen Gruppenmitgliedern in einem Umkreis von 20 Metern die Nahkampfangriffskraft um 306 erhöht. Hält 2 Min. lang an." }
