entries[2070] = { ["name"] = "Kopfnuss", ["text"] = "65 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nBenötigt Verstohlenheit\nMacht ein Ziel bis zu 35 Sek. lang handlungsunfähig. Muss im Verstohlenheitsmodus sein. Wirkt nur bei Humanoiden, die sich nicht im Kampf befinden. Jeglicher erlittene Schaden wird das Ziel wiederbeleben. Es kann immer nur ein Ziel von der Fähigkeit 'Kopfnuss' betroffen sein." }
