entries[2098] = { ["name"] = "Ausweiden", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden pro Combopunkt verursacht:\n1 Punkt: (1 + 5 + Angriffskraft * 0.03)-(5 + 5 + Angriffskraft * 0.03) Schaden\n2 Punkte: [1 + (10) + Angriffskraft * 0.06]-[5 + (10) + Angriffskraft * 0.06] Schaden\n3 Punkte: [1 + (15) + Angriffskraft * 0.09]-[5 + (15) + Angriffskraft * 0.09] Schaden\n4 Punkte: [1 + (20) + Angriffskraft * 0.12]-[5 + (20) + Angriffskraft * 0.12] Schaden\n5 Punkte: [1 + (25) + Angriffskraft * 0.15]-[5 + (25) + Angriffskraft * 0.15] Schaden" }
